-- Web push delivery and supervisor-reviewed briefings.
-- Pushes are queued in push_outbox (by supervisors, alert triggers and a forecast job) and sent by the
-- send-push Edge Function. Briefing drafts are generated by generate-briefing-draft, edited by a
-- supervisor, and only reach crew when the supervisor sends them.

create table public.push_outbox (
  id uuid primary key default gen_random_uuid(),
  site_id uuid not null references public.sites(id) on delete cascade,
  kind text not null check (kind in ('manual','alert','forecast','briefing')),
  title text not null check (length(title) between 1 and 120),
  body text not null check (length(body) between 1 and 400),
  target jsonb not null default '{"mode":"all"}'::jsonb,
  dedup_key text unique,
  created_by uuid references auth.users(id),
  status text not null default 'pending' check (status in ('pending','sending','sent','failed')),
  result jsonb,
  created_at timestamptz not null default now(),
  sent_at timestamptz
);
create index push_outbox_pending on public.push_outbox(created_at) where status in ('pending','sending');
create index push_outbox_site on public.push_outbox(site_id,created_at desc);

create table public.briefing_drafts (
  site_id uuid not null references public.sites(id) on delete cascade,
  for_date date not null,
  content jsonb not null default '{}'::jsonb,
  status text not null default 'generating' check (status in ('generating','draft','sent')),
  source text check (source in ('gemini','rules')),
  updated_by uuid references auth.users(id),
  updated_at timestamptz not null default now(),
  sent_at timestamptz,
  primary key(site_id,for_date)
);

alter table public.push_outbox enable row level security;
alter table public.briefing_drafts enable row level security;
revoke all on public.push_outbox,public.briefing_drafts from anon,authenticated;
grant select on public.push_outbox,public.briefing_drafts to authenticated;
grant select,insert,update,delete on public.push_outbox,public.briefing_drafts to service_role;

create policy outbox_supervisor_read on public.push_outbox for select to authenticated using (private.is_site_supervisor(site_id));
-- Supervisors see every draft; crew see only what a supervisor has sent.
create policy drafts_read on public.briefing_drafts for select to authenticated using (
  private.is_site_supervisor(site_id) or (status='sent' and private.is_site_member(site_id)));

alter publication supabase_realtime add table public.briefing_drafts, public.push_outbox;

-- Calls an Edge Function with a JSON body, using the same Vault secrets as private.invoke_function.
create function private.invoke_function_with(p_name text,p_body jsonb) returns bigint
language plpgsql security definer set search_path='' as $$
declare v_base text; v_secret text;
begin
  select decrypted_secret into v_base from vault.decrypted_secrets where name='functions_base_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name='cron_secret';
  if v_base is null or v_secret is null then
    raise warning 'Vault secrets functions_base_url and cron_secret are required to call %',p_name;
    return null;
  end if;
  return net.http_post(url:=v_base||'/'||p_name,
    headers:=jsonb_build_object('Content-Type','application/json','X-Cron-Secret',v_secret),
    body:=p_body,timeout_milliseconds:=120000);
end; $$;
revoke all on function private.invoke_function_with(text,jsonb) from public,anon,authenticated;

-- Members of a site selected by a push target: {"mode":"all"}, {"mode":"users","user_ids":[...]},
-- or {"mode":"near","lat":..,"lon":..,"radius_m":..} (uses each worker's last known position).
create function private.target_members(p_site_id uuid,p_target jsonb) returns table(user_id uuid)
language sql stable security definer set search_path='' as $$
  select m.user_id from public.site_memberships m
  left join public.crew_locations cl on cl.user_id=m.user_id
  where m.site_id=p_site_id and (
    coalesce(p_target->>'mode','all')='all'
    or (p_target->>'mode'='users' and m.user_id::text in (select jsonb_array_elements_text(p_target->'user_ids')))
    or (p_target->>'mode'='near' and cl.location is not null and extensions.st_dwithin(cl.location,
        extensions.st_setsrid(extensions.st_makepoint((p_target->>'lon')::float8,(p_target->>'lat')::float8),4326)::extensions.geography,
        (p_target->>'radius_m')::float8)));
$$;
revoke all on function private.target_members(uuid,jsonb) from public,anon,authenticated;

create function private.validate_target(p_target jsonb) returns void
language plpgsql immutable set search_path='' as $$
begin
  if p_target is null or jsonb_typeof(p_target)<>'object' then raise exception 'Target required' using errcode='22023'; end if;
  case p_target->>'mode'
    when 'all' then null;
    when 'users' then
      if jsonb_typeof(p_target->'user_ids')<>'array' or jsonb_array_length(p_target->'user_ids') not between 1 and 500 then
        raise exception 'Pick between 1 and 500 workers' using errcode='22023'; end if;
      perform (select array_agg(x::uuid) from jsonb_array_elements_text(p_target->'user_ids') x);
    when 'near' then
      if (p_target->>'lat')::float8 not between -90 and 90 or (p_target->>'lon')::float8 not between -180 and 180
        or (p_target->>'radius_m')::float8 not between 50 and 100000 then
        raise exception 'Valid location and radius (50 to 100000 m) required' using errcode='22023'; end if;
    else raise exception 'Unknown target mode' using errcode='22023';
  end case;
end; $$;
revoke all on function private.validate_target(jsonb) from public,anon,authenticated;

-- Supervisor: preview how many targeted workers can actually receive a push.
create function public.push_audience(p_site_id uuid,p_target jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_total int; v_reachable int;
begin
  if not private.is_site_supervisor(p_site_id) then raise exception 'Supervisor role required' using errcode='42501'; end if;
  perform private.validate_target(p_target);
  select count(*), count(*) filter (where exists(select 1 from public.push_subscriptions s
    where s.user_id=t.user_id and s.channel='web_push'))
  into v_total,v_reachable from private.target_members(p_site_id,p_target) t;
  return jsonb_build_object('targeted',v_total,'reachable',v_reachable);
end; $$;

create function public.send_push(p_site_id uuid,p_title text,p_body text,p_target jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
  if not private.is_site_supervisor(p_site_id) then raise exception 'Supervisor role required' using errcode='42501'; end if;
  perform private.validate_target(p_target);
  insert into public.push_outbox(site_id,kind,title,body,target,created_by)
  values(p_site_id,'manual',btrim(p_title),btrim(p_body),p_target,auth.uid()) returning id into v_id;
  return jsonb_build_object('ok',true,'id',v_id);
end; $$;

-- Supervisor: crew roster with last known location and whether each worker can receive pushes.
create function public.list_site_crew(p_site_id uuid) returns table(
  user_id uuid,name text,email text,role text,latitude double precision,longitude double precision,
  accuracy_m real,located_at timestamptz,is_stale boolean,has_push boolean)
language plpgsql stable security definer set search_path='' as $$
begin
  if not private.is_site_supervisor(p_site_id) then raise exception 'Supervisor role required' using errcode='42501'; end if;
  return query
  select m.user_id,coalesce(nullif(u.raw_user_meta_data->>'name',''),split_part(u.email,'@',1))::text,u.email::text,m.role,
    extensions.st_y(cl.location::extensions.geometry),extensions.st_x(cl.location::extensions.geometry),
    cl.accuracy_m,cl.updated_at,coalesce(cl.updated_at<now()-interval '5 minutes',true),
    exists(select 1 from public.push_subscriptions s where s.user_id=m.user_id and s.channel='web_push')
  from public.site_memberships m
  join auth.users u on u.id=m.user_id
  left join public.crew_locations cl on cl.user_id=m.user_id and cl.site_id=m.site_id
  where m.site_id=p_site_id
  order by 2;
end; $$;

-- Queue a push for every new or escalated active alert (warning and stop_work only).
create function private.alert_to_outbox() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_site text; v_msg text;
begin
  if new.status<>'active' or new.level='info' then return new; end if;
  if tg_op='UPDATE' and new.level is not distinct from old.level and old.status='active' then return new; end if;
  select name into v_site from public.sites where id=new.site_id;
  v_msg:=case new.kind
    when 'lightning' then 'Lightning nearby. Stop work and move to shelter.'
    when 'heat' then 'Heat stress is high. Follow rest and water breaks.'
    when 'flood' then 'Flood risk. Avoid low ground and washouts.'
    when 'wildfire' then 'Wildfire nearby. Check smoke and evacuation routes.'
    else 'Severe weather alert. Open the app for details.' end;
  insert into public.push_outbox(site_id,kind,title,body,dedup_key)
  values(new.site_id,'alert',
    case new.level when 'stop_work' then 'STOP WORK · ' else 'Warning · ' end||v_site,
    v_msg,'alert:'||new.id||':'||new.level)
  on conflict(dedup_key) do nothing;
  return new;
end; $$;
create trigger alerts_push after insert or update of level,status on public.alerts
  for each row execute function private.alert_to_outbox();

-- Any new pending push wakes the sender. The minute cron below retries anything missed.
create function private.wake_sender() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  perform private.invoke_function('send-push');
  return null;
exception when others then
  raise warning 'send-push wake failed: %',sqlerrm;
  return null;
end; $$;
create trigger push_outbox_wake after insert on public.push_outbox
  for each statement execute function private.wake_sender();

create function private.flush_push() returns void
language plpgsql security definer set search_path='' as $$
begin
  if exists(select 1 from public.push_outbox where status='pending'
      or (status='sending' and created_at<now()-interval '5 minutes')) then
    perform private.invoke_function('send-push');
  end if;
end; $$;
select cron.schedule('flush-push','* * * * *',$$select private.flush_push()$$);

-- Forecast warning: tomorrow's computed risk is high and the site has crew.
create function private.queue_forecast_warnings() returns integer
language plpgsql security definer set search_path='' as $$
declare r record; v_n integer:=0; v_id uuid;
begin
  for r in
    select s.id,s.name,s.timezone,sr.risk,sr.top_driver from public.sites s
    join public.site_risk sr on sr.site_id=s.id and sr.horizon='tomorrow'
    where sr.risk>=6 and exists(select 1 from public.site_memberships m where m.site_id=s.id)
  loop
    insert into public.push_outbox(site_id,kind,title,body,dedup_key)
    values(r.id,'forecast','Forecast warning · '||r.name,
      'Tomorrow looks risky ('||coalesce(r.top_driver,'multiple hazards')||', risk '||r.risk||'/10). Check the plan before you head out.',
      'forecast:'||r.id||':'||((now() at time zone r.timezone)::date+1)||':'||case when r.risk>=8 then 'high' else 'elevated' end)
    on conflict(dedup_key) do nothing returning id into v_id;
    if v_id is not null then v_n:=v_n+1; end if;
  end loop;
  return v_n;
end; $$;
select cron.schedule('queue-forecast-warnings','20 * * * *',$$select private.queue_forecast_warnings()$$);

-- Briefing drafts ----------------------------------------------------------------------------------

create function public.request_briefing_draft(p_site_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_date date;
begin
  if not private.is_site_supervisor(p_site_id) then raise exception 'Supervisor role required' using errcode='42501'; end if;
  select (now() at time zone timezone)::date+1 into v_date from public.sites where id=p_site_id;
  insert into public.briefing_drafts(site_id,for_date,status,updated_by) values(p_site_id,v_date,'generating',auth.uid())
  on conflict(site_id,for_date) do update set status='generating',updated_at=now(),updated_by=auth.uid()
    where public.briefing_drafts.status<>'sent';
  perform private.invoke_function_with('generate-briefing-draft',jsonb_build_object('site_id',p_site_id));
  return jsonb_build_object('ok',true,'for_date',v_date);
end; $$;

create function public.save_briefing_draft(p_site_id uuid,p_for_date date,p_content jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
  if not private.is_site_supervisor(p_site_id) then raise exception 'Supervisor role required' using errcode='42501'; end if;
  if p_content is null or jsonb_typeof(p_content)<>'object' or length(p_content::text)>20000 then
    raise exception 'Valid briefing content required' using errcode='22023'; end if;
  update public.briefing_drafts set content=p_content,status='draft',updated_by=auth.uid(),updated_at=now()
  where site_id=p_site_id and for_date=p_for_date and status<>'sent';
  if not found then raise exception 'No editable draft for that date' using errcode='P0002'; end if;
  return jsonb_build_object('ok',true);
end; $$;

create function public.send_briefing(p_site_id uuid,p_for_date date) returns jsonb
language plpgsql security definer set search_path='' as $$
declare d public.briefing_drafts; v_site text; v_body text;
begin
  if not private.is_site_supervisor(p_site_id) then raise exception 'Supervisor role required' using errcode='42501'; end if;
  select * into d from public.briefing_drafts where site_id=p_site_id and for_date=p_for_date for update;
  if not found or d.status='generating' then raise exception 'Draft is not ready' using errcode='P0002'; end if;
  if d.status='sent' then return jsonb_build_object('ok',true,'already_sent',true); end if;
  select name into v_site from public.sites where id=p_site_id;
  v_body:=left(coalesce(
    case when d.content->'work_window' is not null and d.content->'work_window'->>'start' is not null
      then 'Work '||(d.content->'work_window'->>'start')||' to '||(d.content->'work_window'->>'end')||'. ' end,'')
    ||coalesce(d.content->>'summary','Open the app for tomorrow''s plan.'),400);
  update public.briefing_drafts set status='sent',sent_at=now(),updated_by=auth.uid(),updated_at=now()
  where site_id=p_site_id and for_date=p_for_date;
  insert into public.push_outbox(site_id,kind,title,body,created_by,dedup_key)
  values(p_site_id,'briefing','Tomorrow''s plan · '||v_site,v_body,auth.uid(),'briefing:'||p_site_id||':'||p_for_date)
  on conflict(dedup_key) do nothing;
  return jsonb_build_object('ok',true);
end; $$;

-- Worker RPCs (service_role only) ------------------------------------------------------------------

create function public.claim_push_outbox(p_limit int default 20) returns setof public.push_outbox
language sql security definer set search_path='' as $$
  update public.push_outbox o set status='sending' where o.id in (
    select id from public.push_outbox where status='pending'
      or (status='sending' and created_at<now()-interval '5 minutes')
    order by created_at limit least(greatest(p_limit,1),100) for update skip locked)
  returning o.*;
$$;

create function public.push_recipients(p_id uuid) returns table(user_id uuid,subscription_id uuid,address text)
language sql stable security definer set search_path='' as $$
  select s.user_id,s.id,s.address from public.push_outbox o
  join lateral private.target_members(o.site_id,o.target) t on true
  join public.push_subscriptions s on s.user_id=t.user_id and s.channel='web_push'
  where o.id=p_id;
$$;

create function public.finish_push(p_id uuid,p_status text,p_result jsonb) returns void
language sql security definer set search_path='' as $$
  update public.push_outbox set status=case when p_status='sent' then 'sent' else 'failed' end,
    result=p_result,sent_at=now() where id=p_id;
$$;

create function public.delete_push_subscription(p_id uuid) returns void
language sql security definer set search_path='' as $$
  delete from public.push_subscriptions where id=p_id;
$$;

create function public.get_briefing_inputs(p_site_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare s public.sites; v_date date; v_brief jsonb;
begin
  select * into s from public.sites where id=p_site_id;
  if not found then raise exception 'Unknown site' using errcode='P0002'; end if;
  v_date:=(now() at time zone s.timezone)::date+1;
  perform private.build_briefing(p_site_id,false);
  select content into v_brief from public.briefings where site_id=p_site_id and for_date=v_date;
  return jsonb_build_object(
    'site',jsonb_build_object('id',s.id,'name',s.name,'latitude',s.latitude,'longitude',s.longitude,
      'timezone',s.timezone,'utility',s.utility,'plant_type',s.plant_type),
    'for_date',v_date,
    'briefing',coalesce(v_brief,'{}'::jsonb),
    'risk',(select coalesce(jsonb_object_agg(horizon,jsonb_build_object('risk',risk,'driver',top_driver)),'{}'::jsonb)
      from public.site_risk where site_id=p_site_id),
    'subscores',(select to_jsonb(x) - 'site_id' from public.site_subscores x where site_id=p_site_id),
    'active_alerts',(select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'level',level)),'[]'::jsonb)
      from public.alerts where site_id=p_site_id and status='active'),
    'neighbors',(select coalesce(jsonb_agg(jsonb_build_object('name',o.name,
        'distance_km',round((extensions.st_distance(o.location,s.location)/1000)::numeric,1),
        'risk_now',(select risk from public.site_risk r where r.site_id=o.id and r.horizon='now'),
        'risk_tomorrow',(select risk from public.site_risk r where r.site_id=o.id and r.horizon='tomorrow'),
        'driver',(select top_driver from public.site_risk r where r.site_id=o.id and r.horizon='tomorrow'))
        order by extensions.st_distance(o.location,s.location)),'[]'::jsonb)
      from public.sites o where o.id<>s.id and extensions.st_dwithin(o.location,s.location,50000))
  );
end; $$;

create function public.store_briefing_draft(p_site_id uuid,p_for_date date,p_content jsonb,p_source text) returns void
language sql security definer set search_path='' as $$
  insert into public.briefing_drafts(site_id,for_date,content,status,source,updated_at)
  values(p_site_id,p_for_date,p_content,'draft',p_source,now())
  on conflict(site_id,for_date) do update set content=excluded.content,status='draft',source=excluded.source,updated_at=now()
    where public.briefing_drafts.status<>'sent';
$$;

-- At 6 PM local, ask for a draft for every monitored site that has crew and no draft yet.
create function private.queue_due_drafts() returns integer
language plpgsql security definer set search_path='' as $$
declare r record; v_n integer:=0;
begin
  for r in select s.id,(now() at time zone s.timezone)::date+1 as d from public.sites s
    where s.eia_plant_id is not null and extract(hour from now() at time zone s.timezone)=18
      and exists(select 1 from public.site_memberships m where m.site_id=s.id)
      and not exists(select 1 from public.briefing_drafts b where b.site_id=s.id and b.for_date=(now() at time zone s.timezone)::date+1)
  loop
    insert into public.briefing_drafts(site_id,for_date,status) values(r.id,r.d,'generating') on conflict do nothing;
    perform private.invoke_function_with('generate-briefing-draft',jsonb_build_object('site_id',r.id));
    v_n:=v_n+1;
  end loop;
  return v_n;
end; $$;
select cron.schedule('queue-due-drafts','10 * * * *',$$select private.queue_due_drafts()$$);

-- Grants -------------------------------------------------------------------------------------------
revoke all on function public.push_audience(uuid,jsonb),public.send_push(uuid,text,text,jsonb),
  public.list_site_crew(uuid),public.request_briefing_draft(uuid),public.save_briefing_draft(uuid,date,jsonb),
  public.send_briefing(uuid,date),public.claim_push_outbox(int),public.push_recipients(uuid),
  public.finish_push(uuid,text,jsonb),public.delete_push_subscription(uuid),public.get_briefing_inputs(uuid),
  public.store_briefing_draft(uuid,date,jsonb,text) from public,anon,authenticated;
grant execute on function public.push_audience(uuid,jsonb),public.send_push(uuid,text,text,jsonb),
  public.list_site_crew(uuid),public.request_briefing_draft(uuid),public.save_briefing_draft(uuid,date,jsonb),
  public.send_briefing(uuid,date) to authenticated;
grant execute on function public.claim_push_outbox(int),public.push_recipients(uuid),public.finish_push(uuid,text,jsonb),
  public.delete_push_subscription(uuid),public.get_briefing_inputs(uuid),public.store_briefing_draft(uuid,date,jsonb,text) to service_role;
